 public static void ChijieAppliedGroupDamageStopsRemainingEffectsCold()
 {
  var(g,r)=Start(incoming:true,kind:CardKind.BarbarianAssault);Play(g);var hp=Enumerable.Range(0,4).Select(s=>V(g,s).Hp).ToArray();Native(g,g.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.BarbarianAssault));Reach(g,()=>Optional(g,"ol:chijie")&&P(g)!.PlayerSeat==1);Need(V(g,1).Hp==hp[1]-1&&V(g,2).Hp==hp[2]&&E<CompletedUndamagedUseDamageRecordedEvent>(g).Count()==1,"The first real card damage already exists before optional Chijie; later targets have not been damaged.");g=Cold(g,r);Activate(g);Play(g);Need(V(g,1).Hp==hp[1]-1&&V(g,2).Hp==hp[2]&&V(g,3).Hp==hp[3]&&E<ChijieUseInvalidatedEvent>(g).Count()==1,"Only the same native card's remaining effects stop; its first actual damage is retained.");Need(E<ChijieUsedEvent>(g).Single().Branch=="invalidate"&&E<ChijieClaimPaidEvent>(g).Count()==0,"One invalidation consumes the shared actual-turn allowance without claiming a damaging use.");_=Cold(g,r);
  var(chain,registry)=Start(incoming:true,kind:CardKind.FireSlash);Play(chain);Use(chain,"chain",[1]);Play(chain);Use(chain,"chain",[2]);Play(chain);var firstHp=V(chain,1).Hp;var nextHp=V(chain,2).Hp;Native(chain,chain.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.Slash&&a.TargetSeats.SequenceEqual([1])));Reach(chain,()=>Optional(chain,"ol:chijie")&&P(chain)!.PlayerSeat==1);Need(V(chain,1).Hp==firstHp-1&&V(chain,2).Hp==nextHp&&chain.ResolutionStack.OfType<CardUseFrame>().Any(f=>f.CardKind==CardKind.FireSlash&&f.CardAttack?.ChainedTargetSeats.Contains(2)==true),"The real elemental native attack has applied its first damage and already captured the next chained recipient before Chijie acts.");chain=Cold(chain,registry);Activate(chain);Play(chain);Need(V(chain,1).Hp==firstHp-1&&V(chain,2).Hp==nextHp&&E<DamageAppliedEvent>(chain).Count()==1&&E<CompletedUndamagedUseDamageRecordedEvent>(chain).Count()==1&&E<ChijieUseInvalidatedEvent>(chain).Count()==1,"The exact native remaining-damage gate blocks already-queued fire propagation without retracting the first applied damage or creating another damage fact.");_=Cold(chain,registry);
 }
    private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];private static PendingDecision?P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p!=null);
    private static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}private static void Accept(GameEngine g,GameCommand c){var x=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(x.Accepted,(x.Error?.Message??"Rejected XinPi command.")+" "+Diagnostic(g));}private static void Answer(GameEngine g,Func<PromptChoice,bool>test){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(test).Id,g.Revision));}
    private static void Use(GameEngine g,string id,IReadOnlyList<int>targets)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,[],targets,g.Revision,P(g)!.PromptId));private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
